do_elseif.value:
not $ship.isoperational or $ship.owner != faction.player or $ship.trueowner != faction.player
                   or $ship == player.ship or $ship == player.occupiedship or $ship == player.controlled
                   or $ship == player.container or @player.entity.hascontext.{$ship}

not @$captain.isclass.npc or $captain == player.entity or $captain.owner != faction.player
                   or $ship.pilot != $captain or $captain.assignedcontrolled != $ship
                   or $captain.ship != $ship or not @$captain.hascontext.{$ship}
